import{exportSqliteDatabase,importSqliteDatabase}from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts";
import corpus from"../../🧫️fixtures/🪶️sqlite/🔣️.json";
test("Playbook independent two-table producer preserves the arbitrary owned flow handle and nullable title",async()=>{for(const title of[null,corpus.snapshot.title]){const s={...corpus.snapshot,title},d=await playbookSnapshotToSqliteDatabase(s),oracle=new Database(":memory:");try{oracle.exec("PRAGMA application_id=1397576526;PRAGMA user_version=1");oracle.exec(PLAYBOOK_SQLITE_SCHEMA);for(const table of d.tables)for(const row of table.rows)oracle.query(`INSERT INTO ${table.name} VALUES(${row.values.map(()=>"?").join(",")})`).run(...row.values);expect(oracle.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(oracle.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(await playbookSnapshotFromSqliteDatabase(await importSqliteDatabase(oracle.serialize()))).toEqual(s);oracle.query("UPDATE playbook_document SET title=?").run(corpus.editedTitle);oracle.query("UPDATE playbook_flow_child SET artifact_id=?").run(corpus.editedTarget);const back=await playbookSnapshotFromSqliteDatabase(await importSqliteDatabase(oracle.serialize()));expect(back.title).toBe(corpus.editedTitle);expect(back.flow.target.artifactId).toBe(corpus.editedTarget);expect(back.flow.childId).toBe(s.flow.childId);expect(back.flow.target.dialect).toEqual(s.flow.target.dialect);}finally{oracle.close();}}});
test("Playbook physical export refuses malformed relation identities, shape, storage and schema",async()=>{const d=await playbookSnapshotToSqliteDatabase(corpus.snapshot);for(const sql of["DELETE FROM playbook_flow_child","UPDATE playbook_flow_child SET id=2","UPDATE playbook_document SET schema_id=x'00'","UPDATE playbook_document SET title=x'00'","INSERT INTO playbook_document VALUES(2,'extra','','',NULL)"]){const native=Database.deserialize(await exportSqliteDatabase(d));try{native.exec(sql);await expect(playbookSnapshotFromSqliteDatabase(await importSqliteDatabase(native.serialize()))).rejects.toThrow();}finally{native.close();}}const bad={tables:d.tables.map((table,i)=>i===0?{...table,sql:table.sql.replace("schema_id TEXT NOT NULL","schema_id TEXT")}:table)};await expect(playbookSnapshotFromSqliteDatabase(bad)).rejects.toThrow();await expect(playbookSnapshotToSqliteDatabase({...corpus.snapshot,flow:undefined} as unknown as typeof corpus.snapshot)).rejects.toThrow();});
test("Playbook bounds and cancellation precede large owned field copies",async()=>{const huge={...corpus.snapshot,title:"文".repeat(40000)};await expect(playbookSnapshotToSqliteDatabase(huge,{maxValueBytes:16})).rejects.toThrow("value limit");await expect(playbookSnapshotToSqliteDatabase(corpus.snapshot,{maxRows:1})).rejects.toThrow("row limit");const signal=new AbortController();await expect(playbookSnapshotToSqliteDatabase(huge,{signal:signal.signal,onProgress:p=>{if(p.completed>0)signal.abort();}})).rejects.toHaveProperty("kind","canceled");const d=await playbookSnapshotToSqliteDatabase(corpus.snapshot),stop=new AbortController();await expect(playbookSnapshotFromSqliteDatabase(d,{signal:stop.signal,onProgress:p=>{if(p.phase==="reconstructSnapshot")stop.abort();}})).rejects.toHaveProperty("kind","canceled");});

test("direct Playbook projection admits exactly its two domain rows",async()=>{const d=await playbookSnapshotToSqliteDatabase(corpus.snapshot,{maxRows:2});expect(d.tables.reduce((n,t)=>n+t.rows.length,0)).toBe(2);expect(await playbookSnapshotFromSqliteDatabase(d,{maxRows:2})).toEqual(corpus.snapshot);const independent=Database.deserialize(await exportSqliteDatabase(d,{maxRows:2}));try{expect(independent.query("SELECT count(*) AS n FROM playbook_document").get()).toEqual({n:1});}finally{independent.close();}});

