test("Playbook complete literal cells have independent exact and one-short semantic limits",async()=>{
 for(const title of[null,corpus.snapshot.title,corpus.editedTitle]){
  const source={...corpus.snapshot,title},d=await playbookSnapshotToSqliteDatabase(source),db=Database.deserialize(await exportSqliteDatabase(d),{safeIntegers:true});let bytes:number;
  try{const parent=db.query("SELECT 8+length(CAST(schema_id AS BLOB))+length(CAST(document_id AS BLOB))+length(CAST(version AS BLOB))+COALESCE(length(CAST(title AS BLOB)),0) AS bytes FROM playbook_document").get() as {bytes:bigint};const child=db.query("SELECT 8+length(CAST(child_id AS BLOB))+length(CAST(artifact_id AS BLOB))+length(CAST(artifact_kind AS BLOB))+length(CAST(standard AS BLOB))+length(CAST(subset AS BLOB)) AS bytes FROM playbook_flow_child").get() as {bytes:bigint};bytes=Number(parent.bytes+child.bytes);const e=new TextEncoder(),f=source.flow,t=f.target,a=t.dialect;expect(bytes).toBe(16+[source.schema,source.id,source.version,title??"",f.childId,t.artifactId,a.artifactKind,a.standard,a.subset].reduce((n,text)=>n+e.encode(text).length,0));}finally{db.close()}
  expect(await playbookSnapshotToSqliteDatabase(source,{maxRows:2,maxValueBytes:bytes})).toEqual(d);expect(await playbookSnapshotFromSqliteDatabase(d,{maxRows:2,maxValueBytes:bytes})).toEqual(source);
  await expect(playbookSnapshotToSqliteDatabase(source,{maxValueBytes:bytes-1})).rejects.toThrow();await expect(playbookSnapshotFromSqliteDatabase(d,{maxValueBytes:bytes-1})).rejects.toThrow();
 }
});

