fn fixture()->PlaybookSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let s=&f["snapshot"];let f=&s["flow"];let ft=&f["target"];let fd=&ft["dialect"];PlaybookSnapshot{schema:s["schema"].as_str().unwrap().into(),id:s["id"].as_str().unwrap().into(),version:s["version"].as_str().unwrap().into(),title:s["title"].as_str().map(String::from),flow:store::ArtifactChild::new(f["childId"].as_str().unwrap().into(),store::os_io::ArtifactRef{artifact_id:ft["artifactId"].as_str().unwrap().into(),dialect:store::os_io::ArtifactDialect{artifact_kind:fd["artifactKind"].as_str().unwrap().into(),standard:fd["standard"].as_str().unwrap().into(),subset:fd["subset"].as_str().unwrap().into()}})}}
fn project(s:&PlaybookSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<PlaybookSnapshot,ValueError>{PlaybookSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]fn sqlite_snapshot_playbook_independent_sqlite_queries_and_owned_edit(){use std::io::Write;use std::process::{Command,Stdio};let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const f=d.query('SELECT child_id,artifact_id FROM playbook_flow_child').get();if(f.child_id===f.artifact_id)throw Error('distinct target');d.query(\"UPDATE playbook_document SET title='independent playbook title 日本'\").run();d.query(\"UPDATE playbook_flow_child SET artifact_id='independent target β'\").run();await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let back=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(back.title.as_deref(),Some("independent playbook title 日本"));assert_eq!(back.flow.target.artifact_id,"independent target β");assert_eq!(back.flow.child_id,s.flow.child_id);assert_eq!(back.flow.target.dialect,s.flow.target.dialect);}
#[test]fn sqlite_snapshot_playbook_bad_owned_rows_and_bounded_cancellation(){let d=project(&fixture());for case in 0..5{let mut bad=d.clone();match case{0=>bad.table_mut("playbook_flow_child").unwrap().rows.clear(),1=>bad.table_mut("playbook_flow_child").unwrap().rows[0].values[0]=SqliteValue::Integer(2),2=>bad.table_mut("playbook_document").unwrap().rows[0].values[1]=SqliteValue::Blob(vec![0]),3=>bad.table_mut("playbook_document").unwrap().rows[0].values[4]=SqliteValue::Blob(vec![0]),_=>bad.table_mut("playbook_document").unwrap().sql=bad.table("playbook_document").unwrap().sql.replace("schema_id TEXT NOT NULL","schema_id TEXT")};assert!(restore(&bad).is_err());}assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()})).is_err());assert!(PlaybookSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());let mut large=fixture();large.title=Some("文".repeat(40000));assert!(large.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut|p|p.completed==0,SqliteDatabaseLimits::default())).is_err());}
#[test]fn sqlite_snapshot_playbook_owned_fields_and_title_presence(){for title in[None,Some(String::new())]{let mut s=fixture();s.title=title;let d=project(&s);assert_eq!(d.tables.len(),2);let back=restore(&import_sqlite_database(&export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(back,s);assert_ne!(back.flow.child_id,back.flow.target.artifact_id);}}

#[test]fn sqlite_snapshot_playbook_exact_two_domain_rows_need_no_metadata_reservation(){let s=fixture();let d=s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).unwrap();assert_eq!(d.tables.iter().map(|t|t.rows.len()).sum::<usize>(),2);assert_eq!(PlaybookSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).unwrap(),s);}

