  let mut child=Command::new("bun").arg("-e").arg("import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});try{if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const p=d.query('SELECT 8+length(CAST(schema_id AS BLOB))+length(CAST(document_id AS BLOB))+length(CAST(version AS BLOB))+COALESCE(length(CAST(title AS BLOB)),0) AS bytes FROM playbook_document').get(),c=d.query('SELECT 8+length(CAST(child_id AS BLOB))+length(CAST(artifact_id AS BLOB))+length(CAST(artifact_kind AS BLOB))+length(CAST(standard AS BLOB))+length(CAST(subset AS BLOB)) AS bytes FROM playbook_flow_child').get();console.log(Number(p.bytes+c.bytes))}finally{d.close()}").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let cells:String=String::from_utf8(output.stdout).unwrap();let cells:usize=cells.trim().parse().unwrap();
